mapper.update:
UPDATE sys_social_sync_log
SET stage = #{stage},
    cursor_info = #{cursorInfo}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND status = 'RUNNING'

mapper.delete:
DELETE FROM sys_social_sync_log
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND status != 'RUNNING'

mapper.select:
SELECT 
FROM sys_social_sync_log
WHERE tenant_id = #{tenantId}

    AND connection_id = #{connectionId}


    AND sync_type = #{syncType}


    AND status = #{status}

ORDER BY id DESC

SELECT id, tenant_id, connection_id, sync_log_id, object_type, external_id, issue_code, issue_summary,
       process_status, process_action, process_by, process_time, retry_count,
       create_time, update_time, del_flag
FROM sys_social_sync_issue
WHERE tenant_id = #{tenantId}
  AND connection_id = #{connectionId}
  AND object_type = #{objectType}
  AND external_id = #{externalId}
  AND process_status = 'PENDING'
  AND del_flag = 0
LIMIT 1

SELECT id, tenant_id, connection_id, sync_log_id, object_type, external_id, issue_code, issue_summary,
       process_status, process_action, process_by, process_time, retry_count,
       create_time, update_time, del_flag
FROM sys_social_sync_issue
WHERE tenant_id = #{tenantId}
  AND del_flag = 0

    AND connection_id = #{query.connectionId}


    AND sync_log_id = #{query.syncLogId}


    AND object_type = #{query.objectType}


    AND process_status = #{query.processStatus}


    AND issue_code = #{query.issueCode}

ORDER BY id DESC

SELECT COUNT(*)
FROM sys_social_sync_issue
WHERE tenant_id = #{tenantId}
  AND connection_id = #{connectionId}
  AND process_status = 'PENDING'
  AND del_flag = 0
